import React, { useState } from "react";

export default function App() {
  const [form, setForm] = useState({
    disease: "",
    intent: "",
    location: "",
    age: "",
    gender: "",
    what_if: ""
  });

  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(false);

  const handleChange = (e) => {
    setForm({ ...form, [e.target.name]: e.target.value });
  };

  const handleRun = async () => {
    setLoading(true);

    try {
      const res = await fetch("http://localhost:8000/analyze", {
        method: "POST",
        headers: {
          "Content-Type": "application/json"
        },
        body: JSON.stringify(form)
      });

      const result = await res.json();
      setData(result);
    } catch (err) {
      console.error(err);
    }

    setLoading(false);
  };

  return (
    <div style={{ display: "flex", height: "100vh", background: "#0B1220", color: "white" }}>

      {/* LEFT PANEL */}
      <div style={{ width: 250, padding: 20, borderRight: "1px solid #333" }}>
        <h2>🧠 Copilot</h2>
        <p>Papers: {data?.publications?.length || 0}</p>
        <p>Trials: {data?.clinical_trials?.length || 0}</p>
      </div>

      {/* CENTER */}
      <div style={{ flex: 1, padding: 20 }}>
        <h2>Research Query</h2>

        <input name="disease" placeholder="Disease" onChange={handleChange} />
        <input name="intent" placeholder="Intent" onChange={handleChange} />
        <input name="location" placeholder="Location" onChange={handleChange} />
        <input name="age" placeholder="Age" onChange={handleChange} />
        <input name="gender" placeholder="Gender" onChange={handleChange} />
        <input name="what_if" placeholder="What-if treatment" onChange={handleChange} />

        <button onClick={handleRun}>
          {loading ? "Running..." : "Run Research"}
        </button>

        {data && (
          <div style={{ marginTop: 20 }}>
            <h3>🤖 Summary</h3>
            <p>{data.summary}</p>
          </div>
        )}
      </div>

      {/* RIGHT PANEL */}
      <div style={{ width: 350, padding: 20, borderLeft: "1px solid #333", overflowY: "auto" }}>

        <h3>📄 Papers</h3>
        {data?.publications?.map((p, i) => (
          <div key={i} style={{ marginBottom: 10 }}>
            <strong>{p.title}</strong>
            <p>{p.source} • {p.year}</p>
          </div>
        ))}

        <h3>🧪 Trials</h3>
        {data?.clinical_trials?.map((t, i) => (
          <div key={i} style={{ marginBottom: 10 }}>
            <strong>{t.title}</strong>
            <p>{t.status}</p>
          </div>
        ))}
      </div>

    </div>
  );
}
